const productDialog=document.querySelector('#product-dialog');
document.querySelectorAll('[data-product]').forEach(button=>button.addEventListener('click',()=>{const a=productData.find(p=>p.id===button.dataset.product);document.querySelector('#product-title').textContent=a.name;document.querySelector('#product-category').textContent=a.category+' · '+a.status;document.querySelector('#product-intro').textContent=a.intro;document.querySelector('#product-problem').textContent=a.problem;document.querySelector('#product-solution').textContent=a.solution;document.querySelector('#product-role').textContent=a.role;document.querySelector('#product-note').textContent=a.notes;const img=document.querySelector('#product-detail-image');img.src=a.image;img.alt=a.name+'界面'+(a.id==='shengqu'?'演示':'截图');const link=document.querySelector('#product-detail-link');link.hidden=!a.url;if(a.url)link.href=a.url;else link.removeAttribute('href');productDialog.showModal();productDialog.scrollTop=0;requestAnimationFrame(()=>{if(productDialog.open)window.portfolioMotion?.openImage(button,productDialog,img);});}));
